def take_screenshot(api_key, target_url, render_engine=None, viewport_width=None, viewport_height=None, device_scale_factor=None, full_page=None, wait_until=None, timeout_ms=None, format=None, job_id=None, **_extra):
    import json, os, datetime, re, time, secrets
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0254000" if __import__("os").path.isdir("./environment_mix/0254000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(16))

    def _log_usage(usage_rows, api_key_id, event_type, cost_units, job_id_val=None):
        usage_rows.append({
            "id": _gen_id("u2i_evt"),
            "api_key_id": api_key_id,
            "job_id": job_id_val,
            "event_type": event_type,
            "request_id": _extra.get("request_id"),
            "client_ip": _extra.get("client_ip"),
            "user_agent": _extra.get("user_agent"),
            "cost_units": int(cost_units),
            "created_at": _iso(_utcnow()),
        })

    # ---------------- validation ----------------
    if not isinstance(api_key, str) or not re.fullmatch(r"^u2i_key_[0-9A-HJKMNP-TV-Z]{10,}$", api_key):
        return _err("VALIDATION_ERROR", "api_key is missing or malformed", field="api_key")

    if not isinstance(target_url, str) or not target_url.strip():
        return _err("VALIDATION_ERROR", "target_url is missing or empty", field="target_url")
    try:
        u = urlparse(target_url.strip())
        if u.scheme not in ("http", "https") or not u.netloc:
            return _err("VALIDATION_ERROR", "target_url must be a valid http(s) URI", field="target_url")
    except Exception:
        return _err("VALIDATION_ERROR", "target_url must be a valid URI", field="target_url")

    if render_engine is None:
        render_engine = "chromium"
    if render_engine not in ("chromium",):
        return _err("VALIDATION_ERROR", "render_engine is invalid", field="render_engine")

    # tool schema allows minimum 1; underlying job constraints are stricter; accept tool values but clamp to backend min/max
    def _val_int(name, v):
        if v is None:
            return None
        if isinstance(v, bool) or not isinstance(v, int):
            return _err("VALIDATION_ERROR", f"{name} must be an integer", field=name)
        if v < 1:
            return _err("VALIDATION_ERROR", f"{name} must be >= 1", field=name)
        return v

    vw = _val_int("viewport_width", viewport_width)
    if isinstance(vw, dict) and "error" in vw:
        return vw
    vh = _val_int("viewport_height", viewport_height)
    if isinstance(vh, dict) and "error" in vh:
        return vh

    if vw is None:
        vw = 1280
    if vh is None:
        vh = 720

    # enforce underlying constraints by clamping into allowed range (service-side normalization)
    if vw < 100:
        vw = 100
    if vw > 10000:
        vw = 10000
    if vh < 100:
        vh = 100
    if vh > 10000:
        vh = 10000

    if device_scale_factor is None:
        device_scale_factor = 1
    if isinstance(device_scale_factor, bool) or not isinstance(device_scale_factor, (int, float)):
        return _err("VALIDATION_ERROR", "device_scale_factor must be a number", field="device_scale_factor")
    dsf = float(device_scale_factor)
    if dsf < 0.1:
        return _err("VALIDATION_ERROR", "device_scale_factor must be >= 0.1", field="device_scale_factor")
    # clamp to backend constraint
    if dsf < 0.5:
        dsf = 0.5
    if dsf > 4.0:
        dsf = 4.0

    if full_page is None:
        full_page = False
    if not isinstance(full_page, bool):
        return _err("VALIDATION_ERROR", "full_page must be a boolean", field="full_page")

    if wait_until is None:
        wait_until = "load"
    if wait_until not in ("load", "domcontentloaded", "networkidle0", "networkidle2"):
        return _err("VALIDATION_ERROR", "wait_until is invalid", field="wait_until")

    if timeout_ms is None:
        timeout_ms = 60000
    if isinstance(timeout_ms, bool) or not isinstance(timeout_ms, int):
        return _err("VALIDATION_ERROR", "timeout_ms must be an integer", field="timeout_ms")
    if timeout_ms < 1:
        return _err("VALIDATION_ERROR", "timeout_ms must be >= 1", field="timeout_ms")
    # clamp to backend constraints
    if timeout_ms < 1000:
        timeout_ms = 1000
    if timeout_ms > 180000:
        timeout_ms = 180000

    if format is None:
        format = "png"
    if format not in ("png", "jpeg", "webp"):
        return _err("VALIDATION_ERROR", "format is invalid", field="format")

    if job_id is not None:
        if not isinstance(job_id, str) or not re.fullmatch(r"^u2i_job_[0-9A-HJKMNP-TV-Z]{10,}$", job_id):
            return _err("VALIDATION_ERROR", "job_id is malformed", field="job_id")

    # ---------------- load store ----------------
    api_keys_rows = _load("api_keys.json")
    jobs_rows = _load("screenshot_jobs.json")
    artifacts_rows = _load("image_artifacts.json")
    usage_rows = _load("usage_events.json")

    # authenticate (api_key is an id in this service; allow matching key_prefix too)
    key_row = next((r for r in api_keys_rows if r.get("id") == api_key or r.get("key_prefix") == api_key), None)
    if not key_row:
        return _err("UNAUTHORIZED", "api_key is unknown")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "api_key is not active", status=key_row.get("status"))
    key_id = key_row["id"]

    request_id = _extra.get("request_id")
    if request_id is not None and not isinstance(request_id, str):
        return _err("VALIDATION_ERROR", "request_id must be a string when provided", field="request_id")

    # idempotency by request_id (business rule)
    existing_called_evt = None
    if request_id:
        for e in usage_rows:
            if e.get("api_key_id") == key_id and e.get("request_id") == request_id and e.get("event_type") == "take_screenshot_called":
                existing_called_evt = e
                break
        if existing_called_evt and existing_called_evt.get("job_id"):
            prior_job = next((j for j in jobs_rows if j.get("id") == existing_called_evt.get("job_id") and j.get("api_key_id") == key_id), None)
            if prior_job:
                # log this call as another take_screenshot_called with cost 0 (gateway would still hit; keep observable dynamics)
                _log_usage(usage_rows, key_id, "take_screenshot_called", 0, job_id_val=prior_job.get("id"))
                _save("usage_events.json", usage_rows)
                key_row["last_used_at"] = _iso(_utcnow())
                key_row["updated_at"] = _iso(_utcnow())
                _save("api_keys.json", api_keys_rows)

                job_artifacts = [a for a in artifacts_rows if a.get("job_id") == prior_job.get("id")]
                job_artifacts.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))
                return {
                    "job": prior_job,
                    "artifacts": job_artifacts,
                    "idempotent_reuse": True
                }

    # If caller supplies job_id, reuse existing job if it exists regardless of request_id
    if job_id is not None:
        existing_job = next((j for j in jobs_rows if j.get("id") == job_id and j.get("api_key_id") == key_id), None)
        if existing_job:
            _log_usage(usage_rows, key_id, "take_screenshot_called", 0, job_id_val=existing_job.get("id"))
            _save("usage_events.json", usage_rows)
            key_row["last_used_at"] = _iso(_utcnow())
            key_row["updated_at"] = _iso(_utcnow())
            _save("api_keys.json", api_keys_rows)

            job_artifacts = [a for a in artifacts_rows if a.get("job_id") == existing_job.get("id")]
            job_artifacts.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))
            return {
                "job": existing_job,
                "artifacts": job_artifacts,
                "idempotent_reuse": True
            }

    # ---------------- quota + concurrency ----------------
    now = _utcnow()
    minute_start = now - datetime.timedelta(seconds=60)
    used_last_min = 0
    for e in usage_rows:
        if e.get("api_key_id") != key_id:
            continue
        dt = _parse_iso(e.get("created_at"))
        if dt is None:
            continue
        if dt >= minute_start:
            try:
                used_last_min += int(e.get("cost_units") or 0)
            except Exception:
                pass

    # UTC day quota
    day_start = datetime.datetime(now.year, now.month, now.day, tzinfo=datetime.timezone.utc)
    used_today = 0
    for e in usage_rows:
        if e.get("api_key_id") != key_id:
            continue
        dt = _parse_iso(e.get("created_at"))
        if dt is None:
            continue
        if dt >= day_start:
            try:
                used_today += int(e.get("cost_units") or 0)
            except Exception:
                pass

    per_min_limit = int(key_row.get("requests_per_minute_limit") or 0)
    per_day_limit = int(key_row.get("requests_per_day_limit") or 0)
    if per_min_limit > 0 and used_last_min + 1 > per_min_limit:
        # log refused call (cost 0)
        _log_usage(usage_rows, key_id, "take_screenshot_called", 0, job_id_val=None)
        _save("usage_events.json", usage_rows)
        return _err("RATE_LIMIT", "Rate limit exceeded for this API key (rolling 60s window)", limit=per_min_limit, used=used_last_min)

    if per_day_limit > 0 and used_today + 1 > per_day_limit:
        _log_usage(usage_rows, key_id, "take_screenshot_called", 0, job_id_val=None)
        _save("usage_events.json", usage_rows)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded for this API key (UTC day)", limit=per_day_limit, used=used_today)

    in_flight = 0
    for j in jobs_rows:
        if j.get("api_key_id") == key_id and j.get("status") in ("queued", "running"):
            in_flight += 1
    conc_limit = int(key_row.get("concurrent_jobs_limit") or 0)
    if conc_limit > 0 and in_flight + 1 > conc_limit:
        _log_usage(usage_rows, key_id, "take_screenshot_called", 0, job_id_val=None)
        _save("usage_events.json", usage_rows)
        return _err("CONFLICT", "Concurrent jobs limit exceeded for this API key", limit=conc_limit, in_flight=in_flight)

    # ---------------- create job + usage event ----------------
    new_job_id = job_id if job_id is not None else _gen_id("u2i_job")
    if any(j.get("id") == new_job_id for j in jobs_rows):
        # collision with another key's job id -> treat as conflict
        _log_usage(usage_rows, key_id, "take_screenshot_called", 0, job_id_val=None)
        _save("usage_events.json", usage_rows)
        return _err("CONFLICT", "job_id already exists", field="job_id")

    now_iso = _iso(now)
    job_row = {
        "id": new_job_id,
        "api_key_id": key_id,
        "status": "queued",
        "target_url": target_url.strip(),
        "final_url": None,
        "render_engine": render_engine,
        "viewport_width": int(vw),
        "viewport_height": int(vh),
        "device_scale_factor": dsf,
        "full_page": bool(full_page),
        "wait_until": wait_until,
        "timeout_ms": int(timeout_ms),
        "http_status": None,
        "error_code": None,
        "error_message": None,
        "attempt_count": 0,
        "started_at": None,
        "finished_at": None,
        "expires_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    jobs_rows.append(job_row)

    # charge the call + record call and queue events
    _log_usage(usage_rows, key_id, "take_screenshot_called", 1, job_id_val=new_job_id)
    _log_usage(usage_rows, key_id, "job_queued", 0, job_id_val=new_job_id)

    # persist
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    _save("screenshot_jobs.json", jobs_rows)
    _save("usage_events.json", usage_rows)
    _save("api_keys.json", api_keys_rows)

    # return job with any artifacts (none at creation time)
    job_artifacts = [a for a in artifacts_rows if a.get("job_id") == new_job_id]
    job_artifacts.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))
    return {
        "job": job_row,
        "artifacts": job_artifacts,
        "idempotent_reuse": False,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def get_current_identity(api_key, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0254000" if __import__("os").path.isdir("./environment_mix/0254000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s.astimezone(datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    if not isinstance(api_key, str) or not re.fullmatch(r"u2i_key_[0-9A-HJKMNP-TV-Z]{10,}", api_key):
        return _err("VALIDATION_ERROR", "api_key is missing or malformed", field="api_key")

    api_keys = _load("api_keys.json")
    usage_events = _load("usage_events.json")

    key_row = None
    for r in api_keys:
        if r.get("id") == api_key:
            key_row = r
            break
    if key_row is None:
        for r in api_keys:
            if r.get("key_prefix") == api_key:
                key_row = r
                break
    if key_row is None:
        return _err("UNAUTHORIZED", "api_key is unknown")

    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "api_key is not active", status=key_row.get("status"))

    api_key_id = key_row["id"]
    rpm_limit = int(key_row.get("requests_per_minute_limit", 60))
    rpd_limit = int(key_row.get("requests_per_day_limit", 1000))

    window_start = now - datetime.timedelta(seconds=60)
    day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)

    used_60 = 0
    used_day = 0
    for e in usage_events:
        if e.get("api_key_id") != api_key_id:
            continue
        cost = int(e.get("cost_units", 0) or 0)
        edt = _parse_dt(e.get("created_at"))
        if edt is None:
            continue
        if edt >= window_start:
            used_60 += cost
        if edt >= day_start:
            used_day += cost

    # Record a usage event for observability (0 cost)
    # Not in schema as identity call event; reuse take_screenshot_called would be wrong.
    # So we do not append a fake event type. (Schema enumerates allowed events only.)
    latency_ms = int((time.time() - t0) * 1000)
    return {
        "identity": {
            "api_key_id": api_key_id,
            "key_prefix": key_row.get("key_prefix"),
            "name": key_row.get("name"),
            "status": key_row.get("status"),
            "limits": {
                "requests_per_minute_limit": rpm_limit,
                "requests_per_day_limit": rpd_limit,
                "concurrent_jobs_limit": int(key_row.get("concurrent_jobs_limit", 1)),
            },
            "usage": {
                "last_60s": {"used_cost_units": used_60, "limit": rpm_limit, "remaining": max(0, rpm_limit - used_60)},
                "utc_day": {"used_cost_units": used_day, "limit": rpd_limit, "remaining": max(0, rpd_limit - used_day)},
            },
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
            "last_used_at": key_row.get("last_used_at"),
        },
        "meta": {"latency_ms": latency_ms}
    }

def list_screenshot_jobs(api_key, status=None, created_after=None, created_before=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, re, time, secrets, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0254000" if __import__("os").path.isdir("./environment_mix/0254000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be an ISO8601 string", field=field)
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be an ISO8601 date-time", field=field)

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(16))

    def _log_read(usage_rows, api_key_id):
        usage_rows.append({
            "id": _gen_id("u2i_evt"),
            "api_key_id": api_key_id,
            "job_id": None,
            "event_type": "take_screenshot_called",
            "request_id": _extra.get("request_id"),
            "client_ip": _extra.get("client_ip"),
            "user_agent": _extra.get("user_agent"),
            "cost_units": 0,
            "created_at": _iso(_utcnow()),
        })

    def _encode_cursor(last_created_at, last_id):
        obj = {"last_created_at": last_created_at, "last_id": last_id}
        b = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _decode_cursor(tok):
        if tok is None:
            return None
        # be permissive: accept any string; if it doesn't decode, treat as "start from beginning"
        if not isinstance(tok, str) or tok == "":
            return None
        pad = "=" * ((4 - (len(tok) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((tok + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if "last_created_at" not in obj or "last_id" not in obj:
                return None
            if not isinstance(obj.get("last_created_at"), str) or not isinstance(obj.get("last_id"), str):
                return None
            return obj
        except Exception:
            return None

    # validate
    if not isinstance(api_key, str) or not re.fullmatch(r"^u2i_key_[0-9A-HJKMNP-TV-Z]{10,}$", api_key):
        return _err("VALIDATION_ERROR", "api_key is missing or malformed", field="api_key")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled", "expired"):
        return _err("VALIDATION_ERROR", "status is invalid", field="status")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size out of range (1..200)", field="page_size")

    ca = _parse_dt(created_after, "created_after")
    if isinstance(ca, dict) and "error" in ca:
        return ca
    cb = _parse_dt(created_before, "created_before")
    if isinstance(cb, dict) and "error" in cb:
        return cb
    if ca and cb and ca > cb:
        return _err("VALIDATION_ERROR", "created_after must be <= created_before", field="created_after")

    api_keys_rows = _load("api_keys.json")
    jobs_rows = _load("screenshot_jobs.json")
    usage_rows = _load("usage_events.json")

    key_row = None
    for r in api_keys_rows:
        if r.get("id") == api_key or r.get("key_prefix") == api_key:
            key_row = r
            break
    if not key_row:
        return _err("UNAUTHORIZED", "api_key is unknown")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "api_key is not active", status=key_row.get("status"))
    key_id = key_row["id"]

    # filter
    filtered = [j for j in jobs_rows if j.get("api_key_id") == key_id]
    if status:
        filtered = [j for j in filtered if j.get("status") == status]

    def _job_created_dt(j):
        s = j.get("created_at")
        try:
            if isinstance(s, str) and s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            if isinstance(s, str):
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    if ca:
        filtered = [j for j in filtered if _job_created_dt(j) >= ca]
    if cb:
        filtered = [j for j in filtered if _job_created_dt(j) <= cb]

    # sort newest-first by created_at then id desc
    filtered.sort(key=lambda j: (_job_created_dt(j), j.get("id", "")), reverse=True)

    cursor = _decode_cursor(page_token)
    if cursor:
        last_ca = cursor.get("last_created_at")
        last_id = cursor.get("last_id")
        # apply "after" in the sorted (desc) order: start after the cursor item
        def _after_cursor(j):
            jc = j.get("created_at") or ""
            jid = j.get("id") or ""
            # since list is desc, items "after" have (created_at,id) < (last_created_at,last_id)
            if jc < last_ca:
                return True
            if jc == last_ca and jid < last_id:
                return True
            return False
        filtered = [j for j in filtered if _after_cursor(j)]

    page = filtered[:page_size]
    has_more = len(filtered) > page_size
    next_cursor = None
    if has_more and page:
        next_cursor = _encode_cursor(page[-1].get("created_at") or "", page[-1].get("id") or "")

    # observable dynamics: read logs
    _log_read(usage_rows, key_id)
    _save("usage_events.json", usage_rows)

    return {
        "jobs": page,
        "meta": {
            "page_size": page_size,
            "total": len(filtered),
            "has_more": bool(has_more),
            "next_page_token": next_cursor,
            "latency_ms": int((time.time() - t0) * 1000),
        }
    }

