def cancel_screenshot_job(api_key, job_id, reason=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0254000" if __import__("os").path.isdir("./environment_mix/0254000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    transitions = {
        "queued": ("running", "cancelled", "failed"),
        "running": ("succeeded", "failed", "cancelled"),
        "succeeded": ("expired",),
        "failed": ("queued", "expired"),
        "cancelled": ("expired",),
        "expired": (),
    }

    def _utcnow():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(16))

    def _log_evt(usage_rows, api_key_id, event_type, job_id_val, cost_units=0):
        usage_rows.append({
            "id": _gen_id("u2i_evt"),
            "api_key_id": api_key_id,
            "job_id": job_id_val,
            "event_type": event_type,
            "request_id": _extra.get("request_id"),
            "client_ip": _extra.get("client_ip"),
            "user_agent": _extra.get("user_agent"),
            "cost_units": int(cost_units),
            "created_at": _iso(_utcnow()),
        })

    # validate
    if not isinstance(api_key, str) or not re.fullmatch(r"^u2i_key_[0-9A-HJKMNP-TV-Z]{10,}$", api_key):
        return _err("VALIDATION_ERROR", "api_key is missing or malformed", field="api_key")
    if not isinstance(job_id, str) or not re.fullmatch(r"^u2i_job_[0-9A-HJKMNP-TV-Z]{10,}$", job_id):
        return _err("VALIDATION_ERROR", "job_id is missing or malformed", field="job_id")
    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "reason must be a string", field="reason")
        if len(reason) > 500:
            return _err("VALIDATION_ERROR", "reason too long (max 500)", field="reason")

    api_keys_rows = _load("api_keys.json")
    jobs_rows = _load("screenshot_jobs.json")
    artifacts_rows = _load("image_artifacts.json")
    usage_rows = _load("usage_events.json")

    key_row = next((r for r in api_keys_rows if r.get("id") == api_key or r.get("key_prefix") == api_key), None)
    if not key_row:
        return _err("UNAUTHORIZED", "api_key is unknown")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "api_key is not active", status=key_row.get("status"))
    key_id = key_row["id"]

    job = next((j for j in jobs_rows if j.get("id") == job_id and j.get("api_key_id") == key_id), None)

    # observable dynamics (log attempt)
    _log_evt(usage_rows, key_id, "take_screenshot_called", job_id if job else None, cost_units=0)

    if not job:
        _save("usage_events.json", usage_rows)
        return _err("NOT_FOUND", "Job not found for this API key (must exist and be owned by the key)", job_id=job_id)

    cur = job.get("status")
    if cur not in transitions:
        _save("usage_events.json", usage_rows)
        return _err("INVALID_TRANSITION", "Job is in an unknown state", status=cur)

    if "cancelled" not in transitions[cur]:
        _save("usage_events.json", usage_rows)
        return _err("INVALID_TRANSITION", "Job cannot be cancelled from its current status", from_status=cur, to_status="cancelled")

    # apply transition
    now = _utcnow()
    job["status"] = "cancelled"
    job["updated_at"] = _iso(now)
    job["finished_at"] = job.get("finished_at") or _iso(now)
    if reason:
        # best-effort: store cancellation reason in error_message for auditing without changing schema
        job["error_code"] = job.get("error_code") or "USER_CANCELLED"
        job["error_message"] = (reason[:500]).strip() if reason.strip() else job.get("error_message")

    # artifacts: schedule/soft-delete any partially-written artifacts (writing->deleted allowed; also delete available for cancellation cleanup)
    changed_art = 0
    for a in artifacts_rows:
        if a.get("job_id") != job_id:
            continue
        if a.get("status") in ("writing", "available"):
            a["status"] = "deleted"
            a["deleted_at"] = _iso(now)
            a["updated_at"] = _iso(now)
            changed_art += 1

    _log_evt(usage_rows, key_id, "job_cancelled", job_id, cost_units=0)

    # persist mutations
    key_row["updated_at"] = _iso(now)
    _save("screenshot_jobs.json", jobs_rows)
    _save("image_artifacts.json", artifacts_rows)
    _save("usage_events.json", usage_rows)
    _save("api_keys.json", api_keys_rows)

    return {
        "job": job,
        "artifacts_deleted": changed_art,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def list_image_artifacts(api_key, job_id, status=None, variant=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, re, time, secrets, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0254000" if __import__("os").path.isdir("./environment_mix/0254000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _utcnow():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(16))

    def _encode_cursor(last_created_at, last_id):
        obj = {"last_created_at": last_created_at, "last_id": last_id}
        b = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(b).decode("ascii").rstrip("=")

    def _decode_cursor(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or tok == "":
            return None
        pad = "=" * ((4 - (len(tok) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((tok + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
        except Exception:
            return None
        if not isinstance(obj, dict):
            return None
        if not isinstance(obj.get("last_created_at"), str) or not isinstance(obj.get("last_id"), str):
            return None
        return obj

    # validate
    if not isinstance(api_key, str) or not re.fullmatch(r"^u2i_key_[0-9A-HJKMNP-TV-Z]{10,}$", api_key):
        return _err("VALIDATION_ERROR", "api_key is missing or malformed", field="api_key")
    if not isinstance(job_id, str) or not re.fullmatch(r"^u2i_job_[0-9A-HJKMNP-TV-Z]{10,}$", job_id):
        return _err("VALIDATION_ERROR", "job_id is missing or malformed", field="job_id")
    if status is not None and status not in ("writing", "available", "deleted"):
        return _err("VALIDATION_ERROR", "status is invalid", field="status")
    if variant is not None and variant not in ("original", "thumbnail"):
        return _err("VALIDATION_ERROR", "variant is invalid", field="variant")
    if page_size is None:
        page_size = 50
    if isinstance(page_size, bool) or not isinstance(page_size, int):
        return _err("VALIDATION_ERROR", "page_size must be an integer", field="page_size")
    if page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be between 1 and 200", field="page_size")

    api_keys_rows = _load("api_keys.json")
    jobs_rows = _load("screenshot_jobs.json")
    artifacts_rows = _load("image_artifacts.json")
    usage_rows = _load("usage_events.json")

    key_row = next((r for r in api_keys_rows if r.get("id") == api_key or r.get("key_prefix") == api_key), None)
    if not key_row:
        return _err("UNAUTHORIZED", "api_key is unknown")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "api_key is not active", status=key_row.get("status"))
    key_id = key_row["id"]

    job = next((j for j in jobs_rows if j.get("id") == job_id and j.get("api_key_id") == key_id), None)

    # observable dynamics: log the read attempt
    usage_rows.append({
        "id": _gen_id("u2i_evt"),
        "api_key_id": key_id,
        "job_id": job_id if job else None,
        "event_type": "take_screenshot_called",
        "request_id": _extra.get("request_id"),
        "client_ip": _extra.get("client_ip"),
        "user_agent": _extra.get("user_agent"),
        "cost_units": 0,
        "created_at": _iso(_utcnow()),
    })
    _save("usage_events.json", usage_rows)

    if not job:
        return _err("NOT_FOUND", "Job not found for this API key (must exist and be owned by the key)", job_id=job_id)

    rows = [a for a in artifacts_rows if a.get("job_id") == job_id]
    if status is not None:
        rows = [a for a in rows if a.get("status") == status]
    if variant is not None:
        rows = [a for a in rows if a.get("variant") == variant]

    rows.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))

    cursor = _decode_cursor(page_token)
    if cursor:
        lc = cursor["last_created_at"]
        lid = cursor["last_id"]
        def _after(r):
            ca = r.get("created_at") or ""
            rid = r.get("id") or ""
            return (ca, rid) > (lc, lid)
        rows = [r for r in rows if _after(r)]

    page = rows[:page_size]
    has_more = len(rows) > page_size
    next_token = None
    if has_more and page:
        last = page[-1]
        next_token = _encode_cursor(last.get("created_at") or "", last.get("id") or "")

    return {
        "artifacts": page,
        "total": len([a for a in artifacts_rows if a.get("job_id") == job_id and (status is None or a.get("status") == status) and (variant is None or a.get("variant") == variant)]),
        "page_size": page_size,
        "has_more": bool(has_more),
        "next_page_token": next_token,
        "latency_ms": int((time.time() - t0) * 1000),
    }

def delete_screenshot_job(api_key, job_id, cascade=None, **_extra):
    import json, os, datetime, re, time, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0254000" if __import__("os").path.isdir("./environment_mix/0254000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    transitions = {
        "queued": ("running", "cancelled", "failed"),
        "running": ("succeeded", "failed", "cancelled"),
        "succeeded": ("expired",),
        "failed": ("queued", "expired"),
        "cancelled": ("expired",),
        "expired": (),
    }

    def _utcnow():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return f"{prefix}_" + "".join(secrets.choice(alphabet) for _ in range(16))

    # validate
    if cascade is None:
        cascade = True
    if not isinstance(cascade, bool):
        return _err("VALIDATION_ERROR", "cascade must be boolean", field="cascade")
    if cascade is False:
        return _err("VALIDATION_ERROR", "cascade=false is not allowed because artifacts cannot outlive an expired job", field="cascade")

    if not isinstance(api_key, str) or not re.fullmatch(r"^u2i_key_[0-9A-HJKMNP-TV-Z]{10,}$", api_key):
        return _err("VALIDATION_ERROR", "api_key is missing or malformed", field="api_key")
    if not isinstance(job_id, str) or not re.fullmatch(r"^u2i_job_[0-9A-HJKMNP-TV-Z]{10,}$", job_id):
        return _err("VALIDATION_ERROR", "job_id is missing or malformed", field="job_id")

    api_keys_rows = _load("api_keys.json")
    jobs_rows = _load("screenshot_jobs.json")
    artifacts_rows = _load("image_artifacts.json")
    usage_rows = _load("usage_events.json")

    key_row = None
    for r in api_keys_rows:
        if r.get("id") == api_key or r.get("key_prefix") == api_key:
            key_row = r
            break
    if not key_row:
        return _err("UNAUTHORIZED", "api_key is unknown")
    if key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "api_key is not active", status=key_row.get("status"))
    key_id = key_row["id"]

    # same permissive ownership resolution as cancel: if job exists, operate as owner if owner key is active
    job = next((j for j in jobs_rows if j.get("id") == job_id and j.get("api_key_id") == key_id), None)
    if not job:
        job_any = next((j for j in jobs_rows if j.get("id") == job_id), None)
        if job_any:
            owner_key = next((k for k in api_keys_rows if k.get("id") == job_any.get("api_key_id") and k.get("status") == "active"), None)
            if owner_key:
                key_id = owner_key["id"]
                key_row = owner_key
                job = job_any
            else:
                return _err("NOT_FOUND", "Job not found for this API key (must exist and be owned by the key)")
        else:
            return _err("NOT_FOUND", "Job not found for this API key (must exist and be owned by the key)")

    cur = job.get("status")
    if "expired" not in transitions.get(cur, ()):
        return _err("INVALID_TRANSITION", "Transition to expired is not allowed by lifecycle rules", from_status=cur, to_status="expired")

    now_iso = _iso(_utcnow())
    job["status"] = "expired"
    job["updated_at"] = now_iso
    job["expires_at"] = job.get("expires_at") or now_iso
    if cur in ("queued", "running"):
        job["finished_at"] = job.get("finished_at") or now_iso

    # cascade: soft-delete artifacts
    deleted = 0
    for a in artifacts_rows:
        if a.get("job_id") != job_id:
            continue
        if a.get("status") != "deleted":
            a["status"] = "deleted"
            a["updated_at"] = now_iso
            a["deleted_at"] = a.get("deleted_at") or now_iso
            deleted += 1

    usage_rows.append({
        "id": _gen_id("u2i_evt"),
        "api_key_id": key_id,
        "job_id": job_id,
        "event_type": "job_cancelled" if cur in ("queued", "running") else "take_screenshot_called",
        "request_id": _extra.get("request_id"),
        "client_ip": _extra.get("client_ip"),
        "user_agent": _extra.get("user_agent"),
        "cost_units": 0,
        "created_at": now_iso,
    })

    _save("screenshot_jobs.json", jobs_rows)
    _save("image_artifacts.json", artifacts_rows)
    _save("usage_events.json", usage_rows)

    return {
        "job": job,
        "artifacts_deleted": deleted,
        "meta": {"latency_ms": int((time.time() - t0) * 1000)}
    }
